3	import { PortfolioGrid } from "@/components/our-works/portfolio-grid";
4	import { CtaBanner } from "@/components/shared/cta-banner";
5	
6	export const metadata = createMetadata({
7	  title: "White Label Web Development Portfolio | Boldteq",
8	  description:
9	    "Browse Boldteq's white-label web development portfolio. Real client-ready work built for agencies.",
10	  path: "/our-works",
11	});
12	
13	export default function OurWorksPage() {
14	  return (
15	    <>
16	      <OurWorksHero />
17	      <PortfolioGrid />
18	      <CtaBanner />
19	    </>
20	  );
21	}
