1	/* ============================================================
2	   OurWorksHero — our-works-hero.module.css
3	   ============================================================ */
4	
5	.section {
6	  position: relative;
7	  background-color: #092245;
8	  background-image: url('/images/webflow/hero-background-1.png'),
9	    linear-gradient(180deg, #019ae614 0%, #019ae600 100%);
10	  background-position: 50% 100%, 0 0;
11	  background-repeat: no-repeat, repeat;
12	  background-size: cover, auto;
13	  padding: 64px 5%;
14	  overflow: hidden;
15	  text-align: center;
16	}
17	
18	.container {
19	  position: relative;
20	  z-index: 1;
21	  max-width: 56rem;
22	  margin-left: auto;
23	  margin-right: auto;
24	}
25	
26	/* Badge pill */
27	.badge {
28	  display: inline-block;
29	  font-family: 'Roobert PRO', Arial, sans-serif;
30	  font-size: 12px;
31	  font-weight: 700;
32	  letter-spacing: 0.06em;
33	  text-transform: uppercase;
34	  color: #21cfff;
35	  background-color: rgba(33, 207, 255, 0.12);
36	  border: 1px solid rgba(33, 207, 255, 0.3);
37	  border-radius: 999px;
38	  padding: 5px 14px;
39	  margin-bottom: 20px;
40	}
41	
42	/* Main heading */
43	.heading {
44	  font-family: 'Roobert PRO', Arial, sans-serif;
45	  font-size: 48px;
46	  font-weight: 700;
47	  line-height: 1.18;
48	  color: #fff;
49	  margin: 0 0 20px;
50	}
51	
52	.headingAccent {
53	  background: linear-gradient(90deg, #21cfff, #019ae6);
54	  -webkit-background-clip: text;
55	  -webkit-text-fill-color: transparent;
56	  background-clip: text;
57	}
58	
59	/* Subtitle */
60	.subtitle {
61	  font-family: 'Roobert PRO', Arial, sans-serif;
62	  font-size: 17px;
63	  font-weight: 400;
64	  line-height: 1.65;
65	  color: rgba(255, 255, 255, 0.65);
66	  max-width: 44rem;
67	  margin: 0 auto 40px;
68	}
69	
70	/* Stats badges row */
71	.statsRow {
72	  display: flex;
73	  flex-wrap: wrap;
74	  justify-content: center;
75	  gap: 12px;
76	}
77	
78	.statBadge {
79	  display: inline-flex;
80	  align-items: center;
81	  gap: 8px;
82	  background-color: #fff;
83	  border-radius: 10px;
84	  padding: 10px 16px;
85	  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
86	}
87	
88	.statIcon {
89	  flex-shrink: 0;
90	}
91	
92	.statLabel {
93	  font-family: 'Roobert PRO', Arial, sans-serif;
94	  font-size: 13px;
95	  font-weight: 600;
96	  color: #092245;
97	  white-space: nowrap;
98	}
99	
100	/* Subtle bottom gradient fade */
101	.gradientOverlay {
102	  position: absolute;
103	  bottom: 0;
104	  left: 0;
105	  right: 0;
106	  height: 80px;
107	  background: linear-gradient(to bottom, transparent, #f5f7fa);
108	  pointer-events: none;
109	}
110	
111	/* ============================================================
112	   max-width: 768px (tablet / mobile)
113	   ============================================================ */
114	@media screen and (max-width: 768px) {
115	  .section {
116	    padding: 56px 5% 64px;
117	  }
118	
119	  .heading {
120	    font-size: 32px;
121	  }
122	
123	  .subtitle {
124	    font-size: 15px;
125	  }
