133	    font-size: 26px;
134	  }
135	
136	  .statsRow {
137	    gap: 8px;
138	  }
139	
140	  .statBadge {
141	    padding: 8px 12px;
142	  }
143	
144	  .statLabel {
145	    font-size: 12px;
146	  }
147	}
