1	"use client";
2	
3	import { useState, useMemo, useCallback } from "react";
4	import {
5	  PORTFOLIO_ITEMS,
6	  PORTFOLIO_CATEGORIES,
7	} from "@/lib/constants/portfolio";
8	import type { PortfolioItem } from "@/types/portfolio";
9	import { PortfolioCard } from "./portfolio-card";
10	import { PortfolioPopup } from "./portfolio-popup";
11	import styles from "./portfolio-grid.module.css";
12	
13	type SortOption = "name-asc" | "name-desc";
14	const ITEMS_PER_PAGE = 8;
15	
16	export function PortfolioGrid() {
17	  const [activeCategories, setActiveCategories] = useState<string[]>([]);
18	  const [searchQuery, setSearchQuery] = useState("");
19	  const [sort, setSort] = useState<SortOption>("name-asc");
20	  const [currentPage, setCurrentPage] = useState(1);
21	  const [popupItem, setPopupItem] = useState<PortfolioItem | null>(null);
22	
23	  const filtered = useMemo(() => {
24	    const items = PORTFOLIO_ITEMS.filter((item) => {
25	      const matchesCategory =
26	        activeCategories.length === 0 ||
27	        activeCategories.includes(item.category);
28	      const q = searchQuery.trim().toLowerCase();
29	      const matchesSearch =
30	        q === "" ||
31	        item.name.toLowerCase().includes(q) ||
32	        item.category.toLowerCase().includes(q);
33	      return matchesCategory && matchesSearch;
34	    });
35	
36	    items.sort((a, b) =>
37	      sort === "name-asc"
38	        ? a.name.localeCompare(b.name)
39	        : b.name.localeCompare(a.name)
40	    );
41	
42	    return items;
43	  }, [activeCategories, searchQuery, sort]);
44	
45	  const totalPages = Math.max(1, Math.ceil(filtered.length / ITEMS_PER_PAGE));
46	  const safePage = Math.min(currentPage, totalPages);
47	  const visible = filtered.slice(
48	    (safePage - 1) * ITEMS_PER_PAGE,
49	    safePage * ITEMS_PER_PAGE
50	  );
51	
52	  const toggleCategory = useCallback((cat: string) => {
53	    setActiveCategories((prev) =>
54	      prev.includes(cat) ? prev.filter((c) => c !== cat) : [...prev, cat]
55	    );
56	    setCurrentPage(1);
57	  }, []);
58	
59	  const removeCategory = useCallback((cat: string) => {
60	    setActiveCategories((prev) => prev.filter((c) => c !== cat));
61	    setCurrentPage(1);
62	  }, []);
63	
64	  const clearAll = useCallback(() => {
65	    setActiveCategories([]);
66	    setSearchQuery("");
67	    setCurrentPage(1);
68	  }, []);
69	
70	  const goToPage = useCallback((page: number) => {
71	    setCurrentPage(page);
72	  }, []);
73	
74	  // Build page numbers
75	  const pages: number[] = [];
76	  for (let i = 1; i <= totalPages; i++) pages.push(i);
77	
78	  return (
79	    <>
80	      <section className={styles.section}>
81	        <div className={styles.container}>
82	          {/* ──── Filter Header Bar (search + tags + sort) ──── */}
83	          <div className={styles.filterHeader}>
84	            <input
85	              type="search"
86	              placeholder="Search here..."
87	              value={searchQuery}
88	              onChange={(e) => {
89	                setSearchQuery(e.target.value);
90	                setCurrentPage(1);
91	              }}
92	              className={styles.searchField}
93	              aria-label="Search projects"
94	            />
95	
96	            <div className={styles.tagsArea}>
97	              {activeCategories.length > 0 && (
98	                <>
99	                  <p className={styles.tagsLabel}>Filtering by:</p>
100	                  {activeCategories.map((cat) => {
101	                    const label =
102	                      PORTFOLIO_CATEGORIES.find((c) => c.slug === cat)?.name ??
103	                      cat;
104	                    return (
105	                      <div key={cat} className={styles.activeTag}>
106	                        {label}
107	                        <button
108	                          type="button"
109	                          className={styles.activeTagClose}
110	                          onClick={() => removeCategory(cat)}
111	                          aria-label={`Remove ${label} filter`}
112	                        >
113	                          &times;
114	                        </button>
115	                      </div>
116	                    );
117	                  })}
118	                </>
119	              )}
120	            </div>
121	
122	            {/* Sort hidden on live site — kept in state for future use */}
123	          </div>
124	
125	          {/* ──── Sidebar + Card Grid ──── */}
126	          <div className={styles.filterGrid}>
127	            {/* LEFT SIDEBAR */}
128	            <aside className={styles.sidebar}>
129	              <div className={styles.categoryHeader}>
130	                <h3 className={styles.categoryTitle}>Service Categories</h3>
131	                {activeCategories.length > 0 && (
132	                  <button
133	                    type="button"
134	                    className={styles.clearBtn}
135	                    onClick={clearAll}
136	                  >
137	                    Clear
138	                  </button>
139	                )}
140	              </div>
141	
142	              <div className={styles.categoryList}>
143	                {PORTFOLIO_CATEGORIES.map((cat) => {
144	                  if (cat.slug === "all") return null;
145	
146	                  if (cat.comingSoon) {
147	                    return (
148	                      <label key={cat.slug} className={styles.comingSoonLabel}>
149	                        <input
150	                          type="checkbox"
151	                          disabled
152	                          className={styles.comingSoonCheckbox}
153	                        />
154	                        <span>{cat.name}</span>
155	                        <span className={styles.comingSoonBadge}>
156	                          Coming Soon
157	                        </span>
158	                      </label>
159	                    );
160	                  }
161	
162	                  const isChecked = activeCategories.includes(cat.slug);
163	                  return (
164	                    <label key={cat.slug} className={styles.checkboxLabel}>
165	                      <input
166	                        type="checkbox"
167	                        checked={isChecked}
168	                        onChange={() => toggleCategory(cat.slug)}
169	                        className={styles.checkboxInput}
170	                      />
171	                      <span>{cat.name}</span>
172	                    </label>
173	                  );
174	                })}
175	              </div>
176	            </aside>
177	
178	            {/* RIGHT CONTENT */}
179	            <div>
180	              {filtered.length === 0 ? (
181	                <div className={styles.emptyState}>
182	                  <div className={styles.emptyIcon} aria-hidden="true">
183	                    <svg
184	                      xmlns="http://www.w3.org/2000/svg"
185	                      width="48"
186	                      height="48"
187	                      viewBox="0 0 24 24"
188	                      fill="none"
189	                      stroke="currentColor"
190	                      strokeWidth="1.25"
191	                      strokeLinecap="round"
192	                      strokeLinejoin="round"
193	                    >
194	                      <rect x="3" y="3" width="7" height="7" rx="1" />
195	                      <rect x="14" y="3" width="7" height="7" rx="1" />
196	                      <rect x="3" y="14" width="7" height="7" rx="1" />
197	                      <rect x="14" y="14" width="7" height="7" rx="1" />
198	                    </svg>
199	                  </div>
200	                  <h3 className={styles.emptyTitle}>No results found.</h3>
201	                  <p className={styles.emptyDesc}>
202	                    Try a different filter or search term.
203	                  </p>
204	                  <button
205	                    type="button"
206	                    onClick={clearAll}
207	                    className={styles.emptyBtn}
208	                  >
209	                    Show all projects
210	                  </button>
211	                </div>
212	              ) : (
213	                <>
214	                  <ul className={styles.cardGrid} role="list">
215	                    {visible.map((item, idx) => (
216	                      <li key={item.slug}>
217	                        <PortfolioCard
218	                          item={item}
219	                          onCardClick={setPopupItem}
220	                          eager={safePage === 1 && idx < ITEMS_PER_PAGE}
221	                        />
222	                      </li>
223	                    ))}
224	                  </ul>
225	
226	                  {totalPages > 1 && (
227	                    <div className={styles.pagination}>
228	                      <button
229	                        type="button"
230	                        className={styles.pageBtn}
231	                        onClick={() => goToPage(safePage - 1)}
232	                        disabled={safePage === 1}
233	                        aria-label="Previous page"
234	                      >
235	                        {"<<"}
236	                      </button>
237	
238	                      {pages.map((num) => (
239	                        <button
240	                          key={num}
241	                          type="button"
242	                          className={`${styles.pageBtn} ${num === safePage ? styles.pageBtnActive : ""}`}
243	                          onClick={() => goToPage(num)}
244	                          aria-label={`Page ${num}`}
245	                          aria-current={num === safePage ? "page" : undefined}
246	                        >
247	                          {num}
248	                        </button>
249	                      ))}
250	
251	                      <button
252	                        type="button"
253	                        className={styles.pageBtn}
254	                        onClick={() => goToPage(safePage + 1)}
255	                        disabled={safePage === totalPages}
256	                        aria-label="Next page"
257	                      >
258	                        {">>"}
259	                      </button>
260	                    </div>
261	                  )}
262	                </>
263	              )}
264	            </div>
265	          </div>
266	        </div>
267	      </section>
268	
269	      {/* Popup modal */}
270	      {popupItem && (
271	        <PortfolioPopup
272	          item={popupItem}
273	          onClose={() => setPopupItem(null)}
274	        />
275	      )}
276	    </>
277	  );
278	}
