1	/* ============================================================
2	   PortfolioGrid — matches Webflow our-works.html exactly
3	   Live site: container 1300px, grid 305px+975px, cards 480x470
4	   ============================================================ */
5	
6	.section {
7	  background-color: #f5f7fa;
8	  padding: 20px 5% 40px;
9	}
10	
11	.container {
12	  max-width: 1300px;
13	  margin-left: auto;
14	  margin-right: auto;
15	}
16	
17	/* ---------- Filter header bar (search + tags) ---------- */
18	/* Live: grid-template-columns: 305px 955px 0px — sort is hidden */
19	.filterHeader {
20	  grid-column-gap: 20px;
21	  grid-row-gap: 20px;
22	  border: 1px solid rgba(33, 207, 255, 0.23);
23	  border-radius: 10px;
24	  display: grid;
25	  grid-template-columns: 305px 1fr;
26	  align-items: center;
27	  padding: 10px;
28	  margin-bottom: 20px;
29	  background-color: transparent;
30	}
31	
32	.searchField {
33	  font-family: 'Roobert PRO', Arial, sans-serif;
34	  font-size: 14px;
35	  color: #2b2b2b;
36	  width: 100%;
37	  min-height: 45px;
38	  padding: 0.75rem 2.5rem 0.75rem 1rem;
39	  border: 1px solid rgba(33, 207, 255, 0.23);
40	  border-radius: 10px;
41	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
42	  outline: none;
43	  background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='11' cy='11' r='8' stroke='%236b7280' stroke-width='2'/%3E%3Cline x1='21' y1='21' x2='16.65' y2='16.65' stroke='%236b7280' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E");
44	  background-repeat: no-repeat;
45	  background-position: 94% center;
46	  background-size: 1.5rem;
47	  transition: border-color 0.15s ease;
48	}
49	
50	.searchField::placeholder { color: #9ca3af; }
51	.searchField:focus { border-color: #21cfff; }
52	.searchField::-webkit-search-cancel-button { display: none; }
53	
54	/* Filter tags area */
55	.tagsArea {
56	  display: flex;
57	  flex-wrap: wrap;
58	  gap: 8px;
59	  align-items: center;
60	}
61	
62	.tagsLabel {
63	  font-family: 'Roobert PRO', Arial, sans-serif;
64	  font-size: 13px;
65	  color: #6b7280;
66	  margin: 0;
67	}
68	
69	.activeTag {
70	  display: inline-flex;
71	  align-items: center;
72	  background-color: #082753;
73	  color: #fff;
74	  font-family: 'Roobert PRO', Arial, sans-serif;
75	  font-size: 0.85rem;
76	  font-weight: 500;
77	  padding: 0.5rem 2.5rem 0.5rem 1rem;
78	  border-radius: 10px;
79	  position: relative;
80	  margin: 0.5rem 0.5rem 0.5rem 0;
81	}
82	
83	.activeTagClose {
84	  position: absolute;
85	  right: 8px;
86	  top: 50%;
87	  transform: translateY(-50%);
88	  background: none;
89	  border: none;
90	  color: #fff;
91	  cursor: pointer;
92	  padding: 0;
93	  font-size: 16px;
94	  opacity: 0.5;
95	  line-height: 1;
96	}
97	
98	.activeTagClose:hover { opacity: 1; }
99	
100	/* ---------- Sidebar + Cards grid ---------- */
101	/* Live: grid-template-columns: 305px 975px */
102	.filterGrid {
103	  display: grid;
104	  grid-template-columns: 305px 1fr;
105	  grid-column-gap: 20px;
106	  grid-row-gap: 20px;
107	  align-items: start;
108	}
109	
110	/* Sidebar */
111	.sidebar {
112	  background-color: #fff;
113	  border: 1px solid #dfdfdf;
114	  border-radius: 15px;
115	  padding: 10px;
116	  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
117	  position: sticky;
118	  top: 100px;
119	}
120	
121	.categoryHeader {
122	  display: flex;
123	  align-items: center;
124	  justify-content: space-between;
125	  padding: 0.5rem 0.8rem;
126	}
127	
128	.categoryTitle {
129	  font-family: 'Roobert PRO', Arial, sans-serif;
130	  font-size: 15px;
131	  font-weight: 700;
132	  color: #082753;
133	  margin: 0;
134	}
135	
136	.clearBtn {
137	  font-family: 'Roobert PRO', Arial, sans-serif;
138	  font-size: 13px;
139	  color: #2b2b2b;
140	  background: none;
141	  border: none;
142	  padding: 0;
143	  cursor: pointer;
144	  text-decoration: underline;
145	}
146	
147	.categoryList {
148	  display: flex;
149	  flex-direction: column;
150	}
151	
152	/* Checkbox row */
153	.checkboxLabel {
154	  cursor: pointer;
155	  display: flex;
156	  align-items: center;
157	  padding: 0.3rem 0.8rem;
158	  font-family: 'Roobert PRO', Arial, sans-serif;
159	  font-size: 1rem;
160	  font-weight: 400;
161	  color: #2b2b2b;
162	}
163	
164	.checkboxInput {
165	  color: #dadada;
166	  border: 1px solid #dadada;
167	  border-radius: 5px;
168	  width: 1.25rem;
169	  height: 1.25rem;
170	  margin: 0 0.75rem 0 0;
171	  appearance: none;
172	  cursor: pointer;
173	  flex-shrink: 0;
174	  position: relative;
175	  transition: background-color 0.12s, border-color 0.12s;
176	}
177	
178	.checkboxInput:checked {
179	  background-color: #019ae6;
180	  border-color: #21cfff;
181	}
182	
183	.checkboxInput:checked::after {
184	  content: '';
185	  position: absolute;
186	  left: 5px;
187	  top: 2px;
188	  width: 6px;
189	  height: 10px;
190	  border: solid #fff;
191	  border-width: 0 2px 2px 0;
192	  transform: rotate(45deg);
193	}
194	
195	/* Coming Soon */
196	.comingSoonLabel {
197	  composes: checkboxLabel;
198	}
199	
200	.comingSoonCheckbox {
201	  composes: checkboxInput;
202	  opacity: 0.4;
203	  cursor: default;
204	}
205	
206	.comingSoonBadge {
207	  font-family: 'Roobert PRO', Arial, sans-serif;
208	  font-size: 10px;
209	  font-weight: 500;
210	  color: #019ae6;
211	  background-color: rgba(1, 154, 230, 0.1);
212	  border-radius: 4px;
213	  padding: 2px 6px;
214	  margin-left: auto;
215	  white-space: nowrap;
216	}
217	
218	/* ---------- Card grid (2 columns) ---------- */
219	.cardGrid {
220	  list-style: none;
221	  margin: 0;
222	  padding: 0;
223	  display: grid;
224	  grid-template-columns: 1fr 1fr;
225	  grid-column-gap: 16px;
226	  grid-row-gap: 24px;
227	}
228	
229	/* ---------- Empty state ---------- */
230	.emptyState {
231	  display: flex;
232	  flex-direction: column;
233	  align-items: center;
234	  justify-content: center;
235	  padding: 80px 24px;
236	  text-align: center;
237	}
238	
239	.emptyIcon {
240	  width: 72px;
241	  height: 72px;
242	  border-radius: 16px;
243	  background-color: #ecf7fd;
244	  display: flex;
245	  align-items: center;
246	  justify-content: center;
247	  color: #019ae6;
248	  margin-bottom: 20px;
249	}
250	
251	.emptyTitle {
252	  font-family: 'Roobert PRO', Arial, sans-serif;
253	  font-size: 18px;
254	  font-weight: 700;
255	  color: #092245;
256	  margin: 0 0 8px;
257	}
258	
259	.emptyDesc {
260	  font-family: 'Roobert PRO', Arial, sans-serif;
261	  font-size: 15px;
262	  color: #6b7280;
263	  margin: 0 0 24px;
264	  max-width: 320px;
265	}
266	
267	.emptyBtn {
268	  font-family: 'Roobert PRO', Arial, sans-serif;
269	  font-size: 14px;
270	  font-weight: 700;
271	  color: #fff;
272	  background: linear-gradient(90deg, #21cfff, #019ae6);
273	  border: none;
274	  border-radius: 999px;
275	  padding: 10px 24px;
276	  cursor: pointer;
277	}
278	
279	.emptyBtn:hover { filter: brightness(1.08); }
280	
281	/* ---------- Pagination ---------- */
282	/* Live: 44px buttons, #1a3a6e active, white+shadow inactive */
283	.pagination {
